package com.ecommerce.order; import com.ecommerce.user.User; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="orders") public class Order { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) User user; @Column(name="total_amount",nullable=false,precision=12,scale=2) BigDecimal totalAmount; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) Status status; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) List<OrderItem> items=new ArrayList<>(); @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; @Column(name="updated_at",nullable=false) Instant updatedAt; @PrePersist void c(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void u(){updatedAt=Instant.now();} public UUID getId(){return id;} public User getUser(){return user;} public BigDecimal getTotalAmount(){return totalAmount;} public Status getStatus(){return status;} public List<OrderItem> getItems(){return items;} public void setUser(User v){user=v;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public void setStatus(Status v){status=v;} public enum Status{PAYMENT_PENDING,PAID,CONFIRMED,PROCESSING,SHIPPED,DELIVERED,PAYMENT_FAILED,ORDER_CANCELLED} }
